(310, 'hero', 'title', 'E-commerce Speed. B2B Reliability. Ship Simply With <br class=\"d-none d-md-block\"> <span class=\"moving-gradient-text\">United Couriers.</span>', 0, '2026-08-23 12:02:24'),
(311, 'hero', 'subtitle', 'From First Click to Delivery. Your Gateway to Seamless Shipping Worldwide.', 1, '2026-05-20 15:28:01'),
(312, 'hero', 'badge', 'Trusted by Growing Businesses Across India', 2, '2026-08-14 05:56:22'),
(313, 'about', 'badge', 'About United Worldwide Couriers', 10, '2026-05-20 15:28:01'),
(314, 'about', 'heading', 'One Partner. Infinite Logistics Possibilities.', 11, '2026-07-28 10:38:32'),
(315, 'about', 'description', 'United Worldwide Couriers delivers integrated logistics solutions for modern B2B enterprises, e-commerce brands, and growing businesses. Our services cover international Air Express & Freight, pan-India pickup, customs clearance with documentation support, and fulfilment solutions, all managed under one reliable platform. <br> With a strong operational network and an experienced logistics team, we help clients move shipments efficiently, reduce delays, and manage complex requirements with confidence. Every shipment is handled with proactive coordination, transparent tracking, and dedicated customer support to ensure a smooth and dependable delivery experience.', 12, '2026-07-28 10:39:08'),
(316, 'about', 'feature1_title', 'Tailored Shipping for Every Business Model', 13, '2026-07-28 10:39:42'),
(317, 'about', 'feature1_desc', 'Whether you are a B2B manufacturer, e-commerce brand, distributor, dropshipper, or individual shipper, we manage your complete delivery journey across 220+ countries with speed, visibility, and dependable support.', 14, '2026-07-24 10:21:09'),
(318, 'about', 'feature2_title', 'Smarter Cost for High-Volume Shipping', 15, '2026-05-20 15:28:01'),
(319, 'about', 'feature2_desc', 'Our volume-based pricing, shipment consolidation, and optimized routing solutions help businesses reduce logistics costs while improving efficiency across international operations.', 16, '2026-05-20 15:28:01'),
(320, 'about', 'feature3_title', 'Built to Scale With Your Business', 17, '2026-05-20 15:28:01'),
(321, 'about', 'feature3_desc', 'With warehousing, cross-docking, and fulfilment support, we help businesses scale from hundreds to thousands of shipments a day without compromising service quality, timelines, or customer experience.', 18, '2026-05-20 15:28:01'),
(322, 'process', 'section_tag', 'Getting Started', 0, '2026-07-28 11:12:44'),
(323, 'process', 'heading', 'Start Shipping with United Couriers in 4 Simple Steps', 0, '2026-08-14 09:45:51'),
(324, 'process', 'step_title', 'Create Your Account', 1, '2026-07-28 11:13:40'),
(325, 'process', 'step_desc', 'Sign up and set up your shipping profile to manage orders, bookings, invoices, and tracking from one dashboard.', 1, '2026-07-28 11:12:44'),
(326, 'process', 'step_title', 'Choose Your Service', 2, '2026-07-28 11:13:19'),
(327, 'process', 'step_desc', 'Enter your shipment details and compare available delivery options based on price, speed, and service type.', 2, '2026-07-28 11:12:44'),
(328, 'process', 'step_title', 'Schedule Your Pickup', 3, '2026-07-28 11:14:03'),
(329, 'process', 'step_desc', 'Select your preferred service, confirm the shipment, and book your pickup.', 3, '2026-07-28 11:12:44'),
(330, 'process', 'step_title', 'Track Your Shipment', 4, '2026-07-28 11:14:23'),
(331, 'process', 'step_desc', 'Stay updated from pickup to final delivery with real-time tracking and proactive shipment updates.', 4, '2026-07-28 11:12:45'),
(332, 'service_card', 'label', 'Express Air Freight Solutions', 1, '2026-07-28 11:07:53'),
(333, 'service_card', 'title', 'Air Express Services Built Around Your Needs', 1, '2026-07-28 11:07:53'),
(334, 'service_card', 'description', 'Our Express services are designed to give customers complete flexibility — from faster 3–4 day delivery options to more economical 8–10 day delivery solutions, allowing every customer to choose a service based on their urgency, budget, and delivery timeline.', 1, '2026-07-28 11:07:53'),
(335, 'service_card', 'small1_title', 'Flexible Delivery Options', 1, '2026-07-28 11:07:53'),
(336, 'service_card', 'small1_desc', 'Priority and economy services are designed around your budget and timeline.', 1, '2026-07-28 11:07:53'),
(337, 'service_card', 'small2_title', 'Real Time Tracking', 1, '2026-07-28 11:07:53'),
(338, 'service_card', 'small2_desc', 'Instant tracking updates from pickup to final door-to-door delivery.', 1, '2026-07-28 11:07:53'),
(339, 'service_card', 'label', 'E-commerce Logistics Solutions', 2, '2026-07-28 11:07:53'),
(340, 'service_card', 'title', 'Built for Sellers. Designed for Scale', 2, '2026-07-28 11:08:34'),
(341, 'service_card', 'description', 'Connect your marketplace account directly with our platform and ship orders with ease — starting from lightweight parcels of just 50g to high-volume e-commerce shipments.', 2, '2026-07-28 11:09:04'),
(342, 'service_card', 'small1_title', 'No Platform Fee', 2, '2026-07-28 11:09:29'),
(343, 'service_card', 'small1_desc', 'Reduce costs and protect your margins.', 2, '2026-07-28 11:07:53'),
(344, 'service_card', 'small2_title', 'Complete Fulfilment Support', 2, '2026-07-28 11:07:53'),
(345, 'service_card', 'small2_desc', 'Order processing, pickup, dispatch, tracking, and final delivery.', 2, '2026-07-28 11:07:53'),
(346, 'service_card', 'label', 'Warehousing Solutions', 3, '2026-07-28 11:07:53'),
(347, 'service_card', 'title', 'Store. Manage. Fulfil—Smarter from The USA', 3, '2026-07-28 11:10:25'),
(348, 'service_card', 'description', 'Our US warehousing facility helps businesses reduce delivery timelines, manage inventory efficiently, and fulfil international orders with greater speed, control, and reliability.', 3, '2026-07-28 11:10:55'),
(349, 'service_card', 'small1_title', 'Inventory Management', 3, '2026-07-28 11:07:53'),
(350, 'service_card', 'small1_desc', 'Real-time stock visibility with better operational control.', 3, '2026-07-28 11:07:53'),
(351, 'service_card', 'small2_title', 'Fast Fulfillment', 3, '2026-07-28 11:07:53'),
(352, 'service_card', 'small2_desc', 'Speedy dispatch support for e-commerce and B2B shipments.', 3, '2026-07-28 11:07:53'),
(353, 'services_heading', 'heading', 'Powering Your Business with <span class=\"moving-gradient-text\"> Our Services</span>', 60, '2026-07-28 10:42:57'),
(354, 'services_heading', 'description', 'From urgent documents to high-volume commercial cargo, our logistics solutions are built to move every shipment with speed, precision, and complete reliability.', 61, '2026-07-28 10:45:25'),
(355, 'testimonial_heading', 'heading', 'Trusted by Businesses. Rated by Customers', 70, '2026-05-20 09:59:24'),
(356, 'testimonial_heading', 'description', 'For over 30 years, United Worldwide Couriers has supported businesses and individuals with secure, timely, and dependable logistics solutions. Our clients trust us for consistent service, transparent communication, careful handling, and smooth delivery experiences worldwide.', 71, '2026-05-26 07:58:55'),
(357, 'shipping_solutions', 'card_label', 'B2B Shipments', 1, '2026-07-23 01:03:33'),
(358, 'shipping_solutions', 'card_label', 'Dropshipping', 2, '2026-07-23 00:38:36'),
(359, 'shipping_solutions', 'card_label', 'Marketplaces', 3, '2026-07-23 00:38:36'),
