INSERT INTO `hsn_finder_page` (`id`, `section_type`, `title`, `subtitle`, `description`, `image`, `icon_svg`, `link`, `display_order`, `page_badge_text`, `page_button_text`, `page_tag`, `page_label`, `page_placeholder`, `page_icon_class`, `status`, `created_at`, `updated_at`) VALUES
(1, 'hero', 'HSN Classification <span class=\"moving-gradient-text\"> Made Simple</span>', NULL, 'Want to know a product\'s Indian HSN or US HTS code in a snap? Just upload or take a photo.', NULL, NULL, NULL, 1, 'HSN Finder', 'Capture Again', NULL, NULL, NULL, 'fa-solid fa-camera', 1, '2026-05-26 01:06:21', '2026-07-29 06:09:30'),
(2, 'features_heading', 'How It Works?', NULL, 'Three simple steps to get accurate HSN and HTS codes for your products', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-05-26 01:06:21', '2026-05-26 01:06:21'),
(3, 'features', 'Upload Image', NULL, 'Snap a photo or upload an existing image in JPG, PNG, or WEBP format with a maximum file size of 15MB.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, 'fa-solid fa-image', 1, '2026-05-26 01:06:21', '2026-07-29 06:10:30'),
(4, 'features', 'AI Analysis', NULL, 'Our smart AI analyzes your product, checks materials, structure, features, and other important details for accurate classification.', NULL, NULL, NULL, 4, NULL, NULL, NULL, NULL, NULL, 'fa-solid fa-robot', 1, '2026-05-26 01:06:21', '2026-05-26 01:06:21'),
(5, 'features', 'Get Results', NULL, 'Instantly receive the HSN & HTS codes with confidence scores and additional insights for complex or sensitive products.', NULL, NULL, NULL, 5, NULL, NULL, NULL, NULL, NULL, 'fa-solid fa-file-circle-check', 1, '2026-05-26 01:06:21', '2026-05-26 01:06:21');
